#pragma once

#include "dsp/tock/TockSample.h"

#include <memory>

namespace fcm::dsp
{

// The tock samples that ship with the plugin (docs/specs/tock.md §1). Generated by code, so they
// are original and free to redistribute. The list is append-only: the saved value of the Tock
// Sample parameter is the index. Nothing here runs on the audio thread.
class FactoryTocks
{
  public:
    static constexpr double kSampleRate = 48000.0;

    static int count() noexcept;
    static const char* name(int index) noexcept; // empty when out of range

    // Out-of-range indices give the first sample. Peak-normalised to 1.
    static std::unique_ptr<const TockSample> build(int index);
};

} // namespace fcm::dsp
